import React from 'react';
import { BrowserRouter as Router, Routes, Route } from 'react-router-dom';
import Intro from './components/Intro';
import Home from './components/Home'; // Your login page
import Register from './components/Register';
import AdminDashboard from './components/AdminDashboard';
import CandidateRegistration from './componentsCandidateRegistration';

function App() {
  return (
    <Router>
      <Routes>
        {/* The first page users see at http://localhost:3000/ */}
        <Route path="/" element={<Intro />} />
        
        {/* Where "Get Started" leads to */}
        <Route path="/home" element={<Home />} />
        
        <Route path="/register" element={<Register />} />
        <Route path="/admin" element={<AdminDashboard />} />
        <Route path="/register/candidate" element={<CandidateRegistration />} />
        <Route path="/register/hr" element={<HrRegistration />} />
      </Routes>
    </Router>
  );
}

export default App;
